import com.huawei.wax.runtime.framework.HttpContext;
import com.huawei.wax.utils.exception.ServiceException;

import jakarta.annotation.Resource;

import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

/**
 * 智能报告模板接口类
 *
 * @since 2025-09-26
 */
@Component
public class IntelligentTemplateDelegateImpl implements IntelligentTemplateDelegate {
    private static final Logger LOGGER = LoggerFactory.getLogger(IntelligentTemplateDelegateImpl.class);

    @Resource
    ReportTemplateDao reportTemplateDao;

    @Resource
    CatalogFieldChecker catalogFieldChecker;

    @Override
    public List<ReportTemplate> queryReportTemplateList(HttpContext context) throws ServiceException {
        List<ReportTemplatePO> reportTemplatePOs = reportTemplateDao.selectAll();
        return reportTemplatePOs.stream().map(ConvertUtils::reportTemplatePO2Response).toList();
    }

    @Override
    public ReportTemplate generateReportTemplate(HttpContext context, ReportTemplateInput input)
            throws ServiceException {
        if (input == null || input.getTemplate() == null) {
            LOGGER.error("Invalid request for generateReportTemplate, input or template is null");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.PARAMETER_NULL, "$.template");
        }
        LogResult logResult = LogResult.FAILURE;
        try {
            ReportTemplate template = input.getTemplate();
            ReportTemplatePO reportTemplatePO = ConvertUtils.reportTemplateDTO2PO(template);
            reportTemplatePO.setCreator(HttpContextUtil.getUserName(context));
            reportTemplatePO.setModifier(HttpContextUtil.getUserName(context));
            ReportTemplate response = ConvertUtils.reportTemplatePO2Response(reportTemplatePO);
            reportTemplateDao.insert(reportTemplatePO);
            logResult = LogResult.SUCCESSFUL;
            return response;
        } finally {
            OperationLogUtil.recordOperationLog(I18nId.OPERATION_TEMPLATE_GENERATE, LogLevel.MINOR, logResult, context,
                    Optional.of(input.getTemplate()).map(ReportTemplate::getBasicInfo)
                            .map(BasicInfo::getName).orElse(StringUtils.EMPTY));
        }
    }

    @Override
    public void copyTemplate(HttpContext context, String templateId) throws ServiceException {
        if (templateId == null) {
            LOGGER.error("template id is null");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.PARAMETER_NULL, "$.templateId");
        }
        ReportTemplatePO existTemplatePO = reportTemplateDao.selectByTemplateId(templateId);
        if (existTemplatePO == null) {
            LOGGER.error("template not found");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_NOT_FOUND);
        }
        LogResult logResult = LogResult.FAILURE;
        try {
            existTemplatePO.setTemplateId(UUID.randomUUID().toString());
            existTemplatePO.setTemplateName(existTemplatePO.getTemplateName() + "_copy");
            existTemplatePO.setCreateDate(System.currentTimeMillis());
            existTemplatePO.setModifyDate(System.currentTimeMillis());
            existTemplatePO.setCreator(HttpContextUtil.getUserName(context));
            existTemplatePO.setModifier(HttpContextUtil.getUserName(context));
            existTemplatePO.setStatus("Undeployed");
            reportTemplateDao.insert(existTemplatePO);
            logResult = LogResult.SUCCESSFUL;
        } finally {
            OperationLogUtil.recordOperationLog(I18nId.OPERATION_TEMPLATE_COPY, LogLevel.MINOR, logResult, context,
                    existTemplatePO.getTemplateName());
        }
    }

    @Override
    public SseEmitter dryRunTemplate(HttpContext context, TemplateDryRunInput input) throws ServiceException {
        return null;
    }

    @Override
    public ReportTemplate updataSection(HttpContext context, SectionUpdateInput input) throws ServiceException {
        return null;
    }

    @Override
    public ReportTemplate modifyParagraph(HttpContext context, ParagraphModifyInput input) throws ServiceException {
        return null;
    }

    @Override
    public ReportTemplate publishTemplate(HttpContext context, ReportTemplate input) throws ServiceException {
        if (input == null) {
            LOGGER.error("Invalid request for publishTemplate, input is null");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.PARAMETER_NULL, "$");
        }

        // 验证catalog
        catalogFieldChecker.check(input);

        // 查询模板的当前状态
        ReportTemplatePO existingTemplate = reportTemplateDao.selectByTemplateId(input.getBasicInfo().getId());
        if (existingTemplate == null) {
            LOGGER.error("Template not found.");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_NOT_FOUND);
        }
        // 检查模板是否已发布
        if ("Deployed".equals(existingTemplate.getStatus())) {
            LOGGER.error("Template is already deployed, cannot publish again.");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_HAS_PUBLISH);
        }
        LogResult logResult = LogResult.FAILURE;
        try {
            ReportTemplatePO reportTemplatePO = ConvertUtils.reportTemplateDTO2PO(input);
            reportTemplatePO.setModifier(HttpContextUtil.getUserName(context));
            reportTemplateDao.updateStatusWithDeployed(reportTemplatePO);
            ReportTemplatePO responsePO = reportTemplateDao.selectByTemplateId(input.getBasicInfo().getId());
            logResult = LogResult.SUCCESSFUL;
            return ConvertUtils.reportTemplatePO2Response(responsePO);
        } finally {
            OperationLogUtil.recordOperationLog(I18nId.OPERATION_TEMPLATE_PUBLISH, LogLevel.MINOR, logResult, context,
                    input.getBasicInfo().getName());
        }
    }

    @Override
    public ReportTemplate modifyReportTemplate(HttpContext context, String templateId, ReportTemplateInput input)
            throws ServiceException {
        if (StringUtils.isEmpty(templateId) || input == null || input.getTemplate() == null) {
            LOGGER.error("Invalid request for modifyReportTemplate, templateId is empty or input/template is null");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.PARAMETER_NULL, "$.templateId");
        }
        // 查询模板的当前状态
        ReportTemplatePO existingTemplate = reportTemplateDao.selectByTemplateId(templateId);
        if (existingTemplate == null) {
            LOGGER.error("Template not found for templateId: {}", templateId);
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_NOT_FOUND);
        }
        // 检查模板是否已发布
        if ("Deployed".equals(existingTemplate.getStatus())) {
            LOGGER.error("Template is already deployed, cannot modify directly. templateId: {}", templateId);
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_HAS_PUBLISH);
        }
        LogResult logResult = LogResult.FAILURE;
        try {
            ReportTemplate template = input.getTemplate();
            ReportTemplatePO reportTemplatePO = ConvertUtils.reportTemplateDTO2PO(template);
            ReportTemplate response = ConvertUtils.reportTemplatePO2Response(reportTemplatePO);
            reportTemplatePO.setModifier(HttpContextUtil.getUserName(context));
            reportTemplateDao.updateByTemplateId(templateId, reportTemplatePO);
            logResult = LogResult.SUCCESSFUL;
            return response;
        } finally {
            OperationLogUtil.recordOperationLog(I18nId.OPERATION_TEMPLATE_MODIFY, LogLevel.MINOR, logResult, context,
                    existingTemplate.getTemplateName(), JsonUtils.toJsonString(input));
        }
    }

    @Override
    public ReportTemplate unpublishTemplate(HttpContext context, ReportTemplate input) throws ServiceException {
        if (input == null) {
            LOGGER.error("Invalid request for unpublishTemplate, input is null");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.PARAMETER_NULL, "$");
        }
        LogResult logResult = LogResult.FAILURE;
        try {
            ReportTemplatePO reportTemplatePO = ConvertUtils.reportTemplateDTO2PO(input);
            reportTemplatePO.setModifier(HttpContextUtil.getUserName(context));
            reportTemplateDao.updateStatusWithUndeployed(reportTemplatePO);
            ReportTemplatePO responsePO = reportTemplateDao.selectByTemplateId(input.getBasicInfo().getId());
            logResult = LogResult.SUCCESSFUL;
            return ConvertUtils.reportTemplatePO2Response(responsePO);
        } finally {
            OperationLogUtil.recordOperationLog(I18nId.OPERATION_TEMPLATE_UNPUBLISH, LogLevel.MINOR, logResult, context,
                    input.getBasicInfo().getName());
        }
    }

    @Override
    public List<String> deleteReportTemplate(HttpContext context, String templateId) throws ServiceException {
        if (StringUtils.isEmpty(templateId)) {
            LOGGER.error("Invalid request for deleteReportTemplate, templateId is empty");
            ErrorCodeUtil.throwBadReqExp(CheckErrorCode.PARAMETER_NULL, "$.templateId");
        }
        ReportTemplatePO existTemplate = null;
        LogResult logResult = LogResult.FAILURE;
        try {
            existTemplate = reportTemplateDao.selectByTemplateId(templateId);
            if (existTemplate == null) {
                return List.of(templateId);
            }
            reportTemplateDao.deleteByTemplateId(templateId);
            logResult = LogResult.SUCCESSFUL;
        } finally {
            if (existTemplate != null) {
                OperationLogUtil.recordOperationLog(I18nId.OPERATION_TEMPLATE_DELETE, LogLevel.MINOR, logResult,
                        context, existTemplate.getTemplateName());
            }
        }
        return List.of(templateId);
    }

    @Override
    public ReportTemplate queryReportTemplate(HttpContext context, String templateId) throws ServiceException {
        if (StringUtils.isEmpty(templateId)) {
            LOGGER.error("Invalid request for queryReportTemplate, templateId is empty");
            throw new NCEAgentException();
        }
        ReportTemplatePO responsePO = reportTemplateDao.selectByTemplateId(templateId);
        return ConvertUtils.reportTemplatePO2Response(responsePO);
    }
}
